INSERT INTO restaurants (name, description, cuisine, address, area, city, rating, delivery_time, price_for_two, image_url, is_open) VALUES
  ('Deccan Spice House', 'Authentic Hyderabadi Dum Biryani, royal aromatic kebabs, and rich Mughlai gravies slow-cooked to perfection.', 'Biryani, Mughlai', 'Plot 42, Hitec City Main Road, Opposite Cyber Towers', 'Madhapur', 'Hyderabad', 4.8, '25-35 min', 650, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=800&auto=format&fit=crop&q=80', 1),
  ('Charminar Bites', 'Iconic Old City street delicacies including spicy pathar ka gosht, fragrant sheermal, and charcoal grilled kebabs.', 'Mughlai, Kebabs, Street Food', 'Near Mecca Masjid, Charminar Road', 'Old City', 'Hyderabad', 4.6, '30-40 min', 500, 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?w=800&auto=format&fit=crop&q=80', 1),
  ('Pearl City Kitchen', 'Classic Telugu delicacies, flavorful bagara rice, spicy gongura chicken, and crispy starters.', 'South Indian, Biryani', 'Survey 64, Gachibowli Stadium Road', 'Gachibowli', 'Hyderabad', 4.5, '20-30 min', 550, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?w=800&auto=format&fit=crop&q=80', 1),
  ('Biryani Junction', 'The destination for hearty biryani pots, spicy Andhra curries, and tantalizing starters for celebrations.', 'Biryani, Andhra', 'Main Road, Near Botanical Gardens', 'Kondapur', 'Hyderabad', 4.7, '25-35 min', 600, 'https://images.unsplash.com/photo-1633945274405-b6c8069047b0?w=800&auto=format&fit=crop&q=80', 1),
  ('Garden City Dosa', 'Pure vegetarian South Indian tiffins featuring crispy Ghee Podi Roast Dosa, soft Idlis, and heritage Filter Coffee.', 'South Indian, Pure Veg', '100ft Road, Near CMH Road Metro', 'Indiranagar', 'Bengaluru', 4.9, '20-30 min', 350, 'https://images.unsplash.com/photo-1668236543090-82eba5ee5976?w=800&auto=format&fit=crop&q=80', 1),
  ('Chennai Tiffin House', 'Traditional Tamil Nadu tiffin classics with fragrant coconut chutneys, spicy sambar, and authentic filter kaapi.', 'South Indian, Breakfast', 'Usman Road, T. Nagar Commercial Hub', 'T. Nagar', 'Chennai', 4.7, '25-35 min', 300, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?w=800&auto=format&fit=crop&q=80', 1),
  ('Mumbai Street Kitchen', 'Legendary Mumbai street food: buttery Pav Bhaji, crunchy Bhelpuri, spicy Vada Pav, and refreshing Kulfi.', 'Street Food, Chaat, Fast Food', 'Hill Road, Near Bandra Station', 'Bandra West', 'Mumbai', 4.6, '20-30 min', 400, 'https://images.unsplash.com/photo-1606491956689-2ea866880c84?w=800&auto=format&fit=crop&q=80', 1),
  ('Capital Tandoor', 'Sumptuous North Indian tandoori platters, creamy Dal Makhani, Paneer Tikka, and rich clay-oven roasted naans.', 'North Indian, Mughlai, Tandoor', 'Radial Road 4, Connaught Place Block B', 'Connaught Place', 'Delhi', 4.8, '35-45 min', 800, 'https://images.unsplash.com/photo-1517244683847-7456b63c5969?w=800&auto=format&fit=crop&q=80', 1),
  ('Coastal Curry House', 'Fresh coastal Mangalorean fish curries, spicy Kundapur chicken, Neer Dosa, and sol kadhi beverages.', 'Seafood, Coastal, Mangalorean', '80 Feet Road, 4th Block', 'Koramangala', 'Bengaluru', 4.6, '30-40 min', 750, 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=800&auto=format&fit=crop&q=80', 1),
  ('Royal Thali Kitchen', 'Opulent pure vegetarian Rajasthani and Gujarati thali platters featuring Dal Baati Churma, Ker Sangri, and sweets.', 'North Indian, Thali, Pure Veg', 'Link Road, Near Infinity Mall', 'Andheri West', 'Mumbai', 4.7, '35-45 min', 700, 'https://images.unsplash.com/photo-1610057099443-fde8c4d50f91?w=800&auto=format&fit=crop&q=80', 1),
  ('Andhra Spice Corner', 'Fiery Andhra chili chicken, Nellore fish curry, Gongura mutton, and traditional spice-packed curries.', 'Andhra, South Indian', 'KPHB Colony Phase 3, Temple Road', 'Kukatpally', 'Hyderabad', 4.5, '25-35 min', 500, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=800&auto=format&fit=crop&q=80', 1),
  ('Punjabi Zaika', 'Authentic highway dhaba flavours: Rich Butter Chicken, Amritsari Kulcha, creamy Lassi, and Pindi Chole.', 'North Indian, Punjabi', 'Sector 10 Main Market, Dwarka', 'Dwarka', 'Delhi', 4.6, '30-40 min', 600, 'https://images.unsplash.com/photo-1588166524941-3bf61a9c41db?w=800&auto=format&fit=crop&q=80', 1),
  ('Hyderabad Grill House', 'Juicy Arabian shawarmas, Turkish kebabs, grilled BBQ platters, and garlic toum sauces.', 'Arabian, Grills, Barbecue', 'Road No 12, Banjara Hills Main Road', 'Banjara Hills', 'Hyderabad', 4.5, '25-35 min', 550, 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=800&auto=format&fit=crop&q=80', 1),
  ('Wok and Roll Kitchen', 'Pan-Asian sizzling stir fries, Hakka noodles, crispy Dim Sums, and spicy Manchurian bowls.', 'Chinese, Pan-Asian', 'ITPL Main Road, Prestige Shantiniketan', 'Whitefield', 'Bengaluru', 4.4, '30-40 min', 650, 'https://images.unsplash.com/photo-1541696432-82c6da8ce7bf?w=800&auto=format&fit=crop&q=80', 1),
  ('Sweet Cravings Bakery', 'Artisan handcrafted cakes, Belgian chocolate pastries, freshly baked brownies, and signature cookies.', 'Bakery, Desserts, Beverages', '27th Main, Sector 1, HSR Layout', 'HSR Layout', 'Bengaluru', 4.9, '20-30 min', 450, 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=800&auto=format&fit=crop&q=80', 1),
  ('Chai & Samosa Junction', 'Steaming ginger adrak chai, crispy samosas, kachori with tangy chutneys, and evening street refreshments.', 'Snacks, Beverages, Street Food', 'Near Plaza Cinema, Ranade Road', 'Dadar West', 'Mumbai', 4.5, '15-25 min', 250, 'https://images.unsplash.com/photo-1561047029-3000c68339ca?w=800&auto=format&fit=crop&q=80', 0)
INSERT INTO menu_items (restaurant_id, name, description, category, price, image_url, is_veg, is_available) VALUES
  (1, 'Special Hyderabadi Chicken Dum Biryani', 'Long grain basmati rice, tender chicken pieces marinated in yogurt and spices, slow-cooked in dum sealed pot.', 'Biryani', 349.00, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=800&auto=format&fit=crop&q=80', 0, 1),
