  (1, 'Mirchi Ka Salan', 'Traditional spicy green chilli and peanut-sesame curry served as the quintessential biryani accompaniment.', 'Gravy', 129.00, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=800&auto=format&fit=crop&q=80', 1, 1),
