  (1, 'Khubani Ka Meetha with Cream', 'Sweet stewed dried apricot compote served with fresh cream, royal Hyderabadi dessert.', 'Desserts', 179.00, 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=800&auto=format&fit=crop&q=80', 1, 1),
